-- Cross-domain encyclopedia: concepts, Seerah, Sunnah and lived guidance. Editorial review not claimed.
INSERT OR IGNORE INTO encyclopedia_articles(id,slug,title,arabic_title,subtitle,domain,entry_type,abstract,identity_text,alternate_names,editorial_note,review_status,status,sort_order) VALUES ('healing-shifa','healing-shifa','Healing (Shifāʾ)','الشفاء','Divine agency, means of treatment, and human responsibility','quranic_themes','concept','Quran 26:80 attributes healing to Allah in the words of Ibrahim. This theological affirmation should be read alongside responsible care, without collapsing prayer, physical means and clinical evidence into one category.','Source-linked encyclopedia topic.','Shifa, healing, cure, health, illness','Initial original editorial synthesis; independent scholarly review pending.','editorial_draft','published','10');
INSERT OR IGNORE INTO encyclopedia_sections(id,article_id,heading,section_type,body,sort_order) VALUES ('healing-shifa-s1','healing-shifa','Healing as a Quranic theme','overview','The Quran speaks of healing in different rhetorical and spiritual settings. In 26:80 Ibrahim speaks of Allah as the one who heals him when he is ill. The verse expresses trust and dependence upon God. A responsible reference work does not reduce this statement to a label that can be sold on a bottle or a treatment promised by a website.','1');
INSERT OR IGNORE INTO encyclopedia_sections(id,article_id,heading,section_type,body,sort_order) VALUES ('healing-shifa-s2','healing-shifa','Primary textual context','scripture','Surah al-Shuʿara 26:78–82 presents a sequence of acknowledgments attributed to Ibrahim: divine guidance, provision, healing, death and life. The surrounding verses are necessary for interpretation. Quran 16:69 is a different textual context, describing what emerges from bees and its association with healing. Readers should not assume that every use of shifāʾ carries the same referent or application.','2');
INSERT OR IGNORE INTO encyclopedia_sections(id,article_id,heading,section_type,body,sort_order) VALUES ('healing-shifa-s3','healing-shifa','Faith and practical means','interpretation','A theological claim about ultimate agency differs from a clinical claim about whether a particular intervention works. Seeking professional assessment, using ordinary nourishment, offering supplication and caring for others may belong to different practical levels. When one level is mistaken for another, users can be harmed by promises or delayed treatment.','3');
INSERT OR IGNORE INTO encyclopedia_sections(id,article_id,heading,section_type,body,sort_order) VALUES ('healing-shifa-s4','healing-shifa','Encyclopedia research policy','methodology','This entry should function as a navigational hub linking verses, scholarly interpretation, historical reports and medical topics. Hadith authentication and clinical evaluation require different methods. Quranically does not certify an intervention because the word healing appears near it. A future scholarly review should annotate tafsir positions with named commentators and exact citations.','4');
INSERT OR IGNORE INTO encyclopedia_sections(id,article_id,heading,section_type,body,sort_order) VALUES ('healing-shifa-s5','healing-shifa','Safety and integrity','safety','Serious illness, poisoning or mental-health emergencies require appropriately qualified care. Religious belief should not be manipulated into guilt or promises of guaranteed recovery. The encyclopedia must never imply that a visitor''s faith is deficient because a condition persists.','5');
INSERT OR IGNORE INTO encyclopedia_citations(id,article_id,citation_type,source_title,citation_ref,source_url,source_note,verification_status,sort_order) VALUES ('healing-shifa-r1','healing-shifa','quran','The Quran — Surah al-Shuʿarāʾ','26:80','https://quran.com/26/80','Healing attributed to Allah in Ibrahim''s speech.','pending','1');
INSERT OR IGNORE INTO encyclopedia_citations(id,article_id,citation_type,source_title,citation_ref,source_url,source_note,verification_status,sort_order) VALUES ('healing-shifa-r2','healing-shifa','quran','The Quran — Surah al-Naḥl','16:69','https://quran.com/16/69','Related distinct reference concerning bees.','pending','2');
INSERT OR IGNORE INTO encyclopedia_citations(id,article_id,citation_type,source_title,citation_ref,source_url,source_note,verification_status,sort_order) VALUES ('healing-shifa-r3','healing-shifa','reference','Quranic Arabic Corpus','26:80 translations','https://corpus.quran.com/translation.jsp?chapter=26&verse=80','Linguistic comparison; scholarly interpretation remains pending.','pending','3');
INSERT OR IGNORE INTO encyclopedia_articles(id,slug,title,arabic_title,subtitle,domain,entry_type,abstract,identity_text,alternate_names,editorial_note,review_status,status,sort_order) VALUES ('patience-sabr','patience-sabr','Sabr and Patient Perseverance','الصبر','A Quranic ethical concept, not a demand for silence','quranic_themes','concept','Quran 2:153 links seeking help with patience and prayer, while Surah al-Sharh speaks of ease with hardship. A study of sabr needs the surrounding context and must not be used to silence someone in distress.','Source-linked encyclopedia topic.','Sabr, patience, perseverance, trial, hardship','Initial original editorial synthesis; independent scholarly review pending.','editorial_draft','published','11');
INSERT OR IGNORE INTO encyclopedia_sections(id,article_id,heading,section_type,body,sort_order) VALUES ('patience-sabr-s1','patience-sabr','Defining the concept','overview','Sabr is frequently rendered as patience, but its moral significance may involve steadiness, endurance and restraint. It should not be equated with passively accepting injustice or refusing available help. Quranically keeps the original Arabic term visible because a short English translation may conceal important nuances.','1');
INSERT OR IGNORE INTO encyclopedia_sections(id,article_id,heading,section_type,body,sort_order) VALUES ('patience-sabr-s2','patience-sabr','Quranic anchors','scripture','Quran 2:153 addresses believers about seeking help through patience and prayer. Surah al-Sharh 94:5–6 speaks of ease in connection with hardship. The passages have different audiences and literary contexts. Neither should be turned into a timetable that promises the disappearance of every material problem on a chosen day.','2');
INSERT OR IGNORE INTO encyclopedia_sections(id,article_id,heading,section_type,body,sort_order) VALUES ('patience-sabr-s3','patience-sabr','Practice and social responsibility','interpretation','For someone experiencing hardship, patient perseverance can coexist with seeking advice, lawful action, community support and medical care. A difficult circumstance may require intervention from other people. Appeals to patience should not be used to discourage reporting abuse, asking for financial assistance, pursuing rights or obtaining treatment.','3');
INSERT OR IGNORE INTO encyclopedia_sections(id,article_id,heading,section_type,body,sort_order) VALUES ('patience-sabr-s4','patience-sabr','How to read further','methodology','The reader should follow verse references to the complete passages, then consult accountable tafsir rather than extracting isolated slogans. This encyclopedia identifies introductory references; an independent scholar has not yet approved a comparative tafsir chapter.','4');
INSERT OR IGNORE INTO encyclopedia_citations(id,article_id,citation_type,source_title,citation_ref,source_url,source_note,verification_status,sort_order) VALUES ('patience-sabr-r1','patience-sabr','quran','The Quran — Surah al-Baqarah','2:153','https://quran.com/2/153','Patience and prayer.','pending','1');
INSERT OR IGNORE INTO encyclopedia_citations(id,article_id,citation_type,source_title,citation_ref,source_url,source_note,verification_status,sort_order) VALUES ('patience-sabr-r2','patience-sabr','quran','The Quran — Surah al-Sharh','94:5–6','https://quran.com/94/5','Ease and hardship in context.','pending','2');
INSERT OR IGNORE INTO encyclopedia_articles(id,slug,title,arabic_title,subtitle,domain,entry_type,abstract,identity_text,alternate_names,editorial_note,review_status,status,sort_order) VALUES ('grief','grief','Grief and Bereavement','الحزن والفقد','Emotion, mourning and the Prophetic example','living_guidance','guidance','Sorrow appears in Quranic passages and authenticated accounts of the Prophet''s life. This article connects religious references with compassion and appropriate human support, without medicalizing every experience of grief.','Source-linked encyclopedia topic.','Grief, loss, mourning, bereavement, sadness','Initial original editorial synthesis; independent scholarly review pending.','editorial_draft','published','12');
INSERT OR IGNORE INTO encyclopedia_sections(id,article_id,heading,section_type,body,sort_order) VALUES ('grief-s1','grief','Understanding grief','overview','Bereavement is a human response to loss. Its duration and expressions differ across individuals and cultures. For Muslim readers, religious language may provide meaning without requiring a denial of emotion. A source-linked encyclopedia should distinguish an account of mourning from a prescription about exactly how long sadness must last.','1');
INSERT OR IGNORE INTO encyclopedia_sections(id,article_id,heading,section_type,body,sort_order) VALUES ('grief-s2','grief','Quranic language around trials','scripture','Quran 2:155 speaks of trials involving fear, hunger, and different forms of loss. The adjacent verses discuss a response to calamity. Read as a passage, it acknowledges that real deprivation and loss are part of human experience. The text does not provide a clinical diagnostic checklist.','2');
INSERT OR IGNORE INTO encyclopedia_sections(id,article_id,heading,section_type,body,sort_order) VALUES ('grief-s3','grief','The Prophet''s sorrow','historical','Sahih al-Bukhari 1303 reports the Prophet grieving at the death of his son Ibrahim and expressing sorrow. The narrative matters because it shows emotion and faith in the same account. Its use should be accompanied by the complete hadith and qualified commentary, rather than a simplified moral demand imposed on someone who is mourning.','3');
INSERT OR IGNORE INTO encyclopedia_sections(id,article_id,heading,section_type,body,sort_order) VALUES ('grief-s4','grief','Compassion and support','practice','Care for the bereaved may involve listening, food, companionship, practical assistance and religious observance appropriate to the person. The separate talbina entry explores Aisha''s recommendation of a barley preparation in the setting of illness and grief. None of these sources means that a food is a proven treatment for depression.','4');
INSERT OR IGNORE INTO encyclopedia_sections(id,article_id,heading,section_type,body,sort_order) VALUES ('grief-s5','grief','When extra help matters','safety','If grief results in severe functional deterioration, danger or persistent inability to cope, timely professional assessment is appropriate. Seek emergency assistance when immediate safety is at risk. This is a supportive encyclopedia article, not a diagnosis or individual religious ruling.','5');
INSERT OR IGNORE INTO encyclopedia_citations(id,article_id,citation_type,source_title,citation_ref,source_url,source_note,verification_status,sort_order) VALUES ('grief-r1','grief','quran','The Quran — Surah al-Baqarah','2:155–157','https://quran.com/2/155','Tests and human loss.','pending','1');
INSERT OR IGNORE INTO encyclopedia_citations(id,article_id,citation_type,source_title,citation_ref,source_url,source_note,verification_status,sort_order) VALUES ('grief-r2','grief','hadith','Sahih al-Bukhari','1303','https://sunnah.com/bukhari:1303','Mourning for Ibrahim.','pending','2');
INSERT OR IGNORE INTO encyclopedia_citations(id,article_id,citation_type,source_title,citation_ref,source_url,source_note,verification_status,sort_order) VALUES ('grief-r3','grief','hadith','Sahih al-Bukhari','5689','https://sunnah.com/bukhari:5689','Talbina narration related to grief.','pending','3');
INSERT OR IGNORE INTO encyclopedia_articles(id,slug,title,arabic_title,subtitle,domain,entry_type,abstract,identity_text,alternate_names,editorial_note,review_status,status,sort_order) VALUES ('worry-remembrance','worry-remembrance','Worry and Remembrance','الهم والذكر','Dhikr, prayer and responsible care for anxiety','living_guidance','guidance','Quran 13:28 connects remembrance of Allah with reassurance of the heart. The Islamic sources can be explored without claiming that devotional practices are a substitute for assessment and treatment of anxiety disorders.','Source-linked encyclopedia topic.','Anxiety, worry, dhikr, remembrance, stress, supplication','Initial original editorial synthesis; independent scholarly review pending.','editorial_draft','published','13');
INSERT OR IGNORE INTO encyclopedia_sections(id,article_id,heading,section_type,body,sort_order) VALUES ('worry-remembrance-s1','worry-remembrance','The Quranic reference','scripture','Surah al-Raʿd 13:28 speaks of hearts finding reassurance through remembrance of Allah. The verse is religious guidance in its own context. It should not be interpreted as a measurement of clinical anxiety or a promise of immediate symptom disappearance.','1');
INSERT OR IGNORE INTO encyclopedia_sections(id,article_id,heading,section_type,body,sort_order) VALUES ('worry-remembrance-s2','worry-remembrance','A Prophetic supplication','transmission','Sahih al-Bukhari 6369 transmits a supplication seeking protection from worry, sadness and other burdens. Quranically indexes this source by its collection number and distinguishes the narration from later transliterations or devotional schedules, which require separate accuracy checks.','2');
INSERT OR IGNORE INTO encyclopedia_sections(id,article_id,heading,section_type,body,sort_order) VALUES ('worry-remembrance-s3','worry-remembrance','The lived experience of worry','overview','People experience stress, uncertainty and fear for many reasons. Some difficulties respond to problem-solving and support; others warrant professional mental-health evaluation. Spiritual practice may be meaningful alongside those measures. Persistent symptoms are not evidence of moral or religious failure.','3');
INSERT OR IGNORE INTO encyclopedia_sections(id,article_id,heading,section_type,body,sort_order) VALUES ('worry-remembrance-s4','worry-remembrance','A careful next step','practice','A reader may review the verse in context, learn a well-attested supplication, seek support from trusted people, and identify practical action appropriate to the situation. This entry does not suggest stopping prescribed medicine or undertaking an unverified healing procedure.','4');
INSERT OR IGNORE INTO encyclopedia_sections(id,article_id,heading,section_type,body,sort_order) VALUES ('worry-remembrance-s5','worry-remembrance','Safety considerations','safety','Severe mental-health symptoms, thoughts of self-harm or immediate danger require urgent professional support. Quranically should never reduce such cases to the sale of a supplement or imply that additional recitation alone is sufficient.','5');
INSERT OR IGNORE INTO encyclopedia_citations(id,article_id,citation_type,source_title,citation_ref,source_url,source_note,verification_status,sort_order) VALUES ('worry-remembrance-r1','worry-remembrance','quran','The Quran — Surah al-Raʿd','13:28','https://quran.com/13/28','Remembrance and reassurance.','pending','1');
INSERT OR IGNORE INTO encyclopedia_citations(id,article_id,citation_type,source_title,citation_ref,source_url,source_note,verification_status,sort_order) VALUES ('worry-remembrance-r2','worry-remembrance','hadith','Sahih al-Bukhari','6369','https://sunnah.com/bukhari:6369','Supplication referring to worry and grief.','pending','2');
INSERT OR IGNORE INTO encyclopedia_articles(id,slug,title,arabic_title,subtitle,domain,entry_type,abstract,identity_text,alternate_names,editorial_note,review_status,status,sort_order) VALUES ('debt-responsibility','debt-responsibility','Debt and Responsibility','الدَّيْن والأمانة','Ethics of obligation, compassion and practical resolution','living_guidance','guidance','Quranic and Prophetic references speak to both obligations and compassion in situations of debt. The sources should be read carefully, alongside lawful financial advice rather than promises of debt elimination through rituals.','Source-linked encyclopedia topic.','Debt, loan, borrowing, creditor, finance, hardship','Initial original editorial synthesis; independent scholarly review pending.','editorial_draft','published','14');
INSERT OR IGNORE INTO encyclopedia_sections(id,article_id,heading,section_type,body,sort_order) VALUES ('debt-responsibility-s1','debt-responsibility','The ethical setting','overview','Debt affects relationships, livelihood and trust. It creates obligations for the borrower and responsibilities for lenders and communities. A careful reference work avoids suggesting that every borrowing situation is morally identical or that one financial product fits all legal jurisdictions.','1');
INSERT OR IGNORE INTO encyclopedia_sections(id,article_id,heading,section_type,body,sort_order) VALUES ('debt-responsibility-s2','debt-responsibility','Quranic reference','scripture','Quran 2:280 encourages giving time to a debtor in hardship and relates to the ethics of treatment of those struggling to repay. The wider context and detailed legal interpretation belong to qualified scholarship. This encyclopedia can preserve the reference without issuing a personal ruling.','2');
INSERT OR IGNORE INTO encyclopedia_sections(id,article_id,heading,section_type,body,sort_order) VALUES ('debt-responsibility-s3','debt-responsibility','Reported Prophetic teaching','transmission','Sahih Muslim 1563a includes a report concerning relief for those experiencing debt difficulty. The creditor-facing dimensions of compassion should be distinguished from the borrower''s duty to communicate honestly and pursue responsible solutions.','3');
INSERT OR IGNORE INTO encyclopedia_sections(id,article_id,heading,section_type,body,sort_order) VALUES ('debt-responsibility-s4','debt-responsibility','Practical approach','practice','Keep records of amounts and deadlines, communicate candidly, seek lawful advice and prioritize safety and necessities. Religious supplication may accompany action; it is not a substitute for contractual or legal analysis. Future guidance can link to verified debt-support organizations without making commission-based offers appear as religious mandates.','4');
INSERT OR IGNORE INTO encyclopedia_sections(id,article_id,heading,section_type,body,sort_order) VALUES ('debt-responsibility-s5','debt-responsibility','Limits','safety','This entry is neither a binding fatwa nor regulated legal or financial advice. Financial emergencies, exploitation and creditor abuse may warrant qualified local assistance.','5');
INSERT OR IGNORE INTO encyclopedia_citations(id,article_id,citation_type,source_title,citation_ref,source_url,source_note,verification_status,sort_order) VALUES ('debt-responsibility-r1','debt-responsibility','quran','The Quran — Surah al-Baqarah','2:280','https://quran.com/2/280','Leniency toward debtors in hardship.','pending','1');
INSERT OR IGNORE INTO encyclopedia_citations(id,article_id,citation_type,source_title,citation_ref,source_url,source_note,verification_status,sort_order) VALUES ('debt-responsibility-r2','debt-responsibility','hadith','Sahih Muslim','1563a','https://sunnah.com/muslim:1563a','Relief regarding repayment hardship.','pending','2');
INSERT OR IGNORE INTO encyclopedia_articles(id,slug,title,arabic_title,subtitle,domain,entry_type,abstract,identity_text,alternate_names,editorial_note,review_status,status,sort_order) VALUES ('prophetic-mercy','prophetic-mercy','Mercy in the Prophetic Example','الرحمة في السيرة','Conduct under rejection and the ethics of restraint','seerah','historical','An authenticated narration recounts an episode of rejection and the Prophet''s hopeful response rather than retaliation. The article examines why context matters when turning Seerah into contemporary guidance.','Source-linked encyclopedia topic.','Prophetic mercy, seerah, Taif, rejection, forgiveness','Initial original editorial synthesis; independent scholarly review pending.','editorial_draft','published','15');
INSERT OR IGNORE INTO encyclopedia_sections(id,article_id,heading,section_type,body,sort_order) VALUES ('prophetic-mercy-s1','prophetic-mercy','The episode in the sources','historical','Sahih al-Bukhari 3231 recounts Aisha asking about a difficult day and includes the Prophet''s description of rejection during his mission. A response involving the possibility of punishment is followed by his hope for future worship of Allah. The narrative should not be reduced to a fictionalized scene or stripped of its transmission.','1');
INSERT OR IGNORE INTO encyclopedia_sections(id,article_id,heading,section_type,body,sort_order) VALUES ('prophetic-mercy-s2','prophetic-mercy','Transmission and biography','transmission','An event appearing in a hadith collection can be studied alongside biographical literature, but each tradition has its own evidence questions. An encyclopedia should cite the exact report before introducing details from later Seerah accounts. Where alternative tellings exist, they should be identified rather than merged into a single unattributed story.','2');
INSERT OR IGNORE INTO encyclopedia_sections(id,article_id,heading,section_type,body,sort_order) VALUES ('prophetic-mercy-s3','prophetic-mercy','What the example shows','interpretation','The account can prompt reflection on mercy and restraint in the face of rejection. It does not guarantee that every act of compassion yields immediate worldly success, nor require a victim to remain in an unsafe circumstance. The theological and legal implications require scholarly interpretation.','3');
INSERT OR IGNORE INTO encyclopedia_sections(id,article_id,heading,section_type,body,sort_order) VALUES ('prophetic-mercy-s4','prophetic-mercy','Use in guidance','practice','Connecting this narrative to articles about patience or grief can help users compare authentic sources. The editorial system should record these connections explicitly and distinguish direct text from a modern application.','4');
INSERT OR IGNORE INTO encyclopedia_sections(id,article_id,heading,section_type,body,sort_order) VALUES ('prophetic-mercy-s5','prophetic-mercy','Editorial status','methodology','This entry is a source-linked reading summary, not an independently scholarly reviewed Seerah chapter. Quotations and narrative details must undergo editorial and scholarly verification before presentation as an authoritative account.','5');
INSERT OR IGNORE INTO encyclopedia_citations(id,article_id,citation_type,source_title,citation_ref,source_url,source_note,verification_status,sort_order) VALUES ('prophetic-mercy-r1','prophetic-mercy','hadith','Sahih al-Bukhari','3231','https://sunnah.com/bukhari:3231','Narration about rejection and mercy.','pending','1');
INSERT OR IGNORE INTO encyclopedia_articles(id,slug,title,arabic_title,subtitle,domain,entry_type,abstract,identity_text,alternate_names,editorial_note,review_status,status,sort_order) VALUES ('supplication-dua','supplication-dua','Supplication (Duʿāʾ)','الدعاء','Invocation, transmitted wording and source provenance','sunnah','concept','Supplications recorded in authenticated sources are important for devotional life. This encyclopedia prioritizes exact citation, careful Arabic, attribution and interpretation over unsourced formulas promising fixed worldly results.','Source-linked encyclopedia topic.','Dua, duaa, supplication, invocation, prophetic prayer','Initial original editorial synthesis; independent scholarly review pending.','editorial_draft','published','16');
INSERT OR IGNORE INTO encyclopedia_sections(id,article_id,heading,section_type,body,sort_order) VALUES ('supplication-dua-s1','supplication-dua','What is supplication?','overview','Duʿāʾ is invocation directed toward Allah. Recorded forms appear in the Quran and Sunnah. A text presented as a specifically Prophetic duʿāʾ needs careful attribution; an editor must not conflate a personal prayer with a word-for-word authenticated narration.','1');
INSERT OR IGNORE INTO encyclopedia_sections(id,article_id,heading,section_type,body,sort_order) VALUES ('supplication-dua-s2','supplication-dua','An example from an authenticated source','transmission','Sahih al-Bukhari 6369 reports a supplication that includes seeking protection from worry, grief, incapacity and burdensome debt. Readers need the complete Arabic wording and its actual reference. Transliteration can aid access but remains an imperfect guide to pronunciation.','2');
INSERT OR IGNORE INTO encyclopedia_sections(id,article_id,heading,section_type,body,sort_order) VALUES ('supplication-dua-s3','supplication-dua','Conditions and claims','interpretation','An authentic transmitted supplication is not permission for an editor or marketer to promise a guaranteed result after an invented number of repetitions. Guidance on devotional etiquette and juristic differences requires named scholarly sources. Quranically should avoid circulating unattributed magical-looking routines.','3');
INSERT OR IGNORE INTO encyclopedia_sections(id,article_id,heading,section_type,body,sort_order) VALUES ('supplication-dua-s4','supplication-dua','Responsible access','practice','The encyclopedia should provide authentic text with references, separate learning aids from primary material, and allow copying, printing or listening where legitimate audio rights exist. Personal records can be saved privately, but the platform should not suggest that a log of repetitions changes a user''s medical status.','4');
INSERT OR IGNORE INTO encyclopedia_citations(id,article_id,citation_type,source_title,citation_ref,source_url,source_note,verification_status,sort_order) VALUES ('supplication-dua-r1','supplication-dua','hadith','Sahih al-Bukhari','6369','https://sunnah.com/bukhari:6369','Authenticated supplication about worry, grief and debt.','pending','1');
INSERT OR IGNORE INTO encyclopedia_citations(id,article_id,citation_type,source_title,citation_ref,source_url,source_note,verification_status,sort_order) VALUES ('supplication-dua-r2','supplication-dua','quran','The Quran — Surah Ghafir','40:60','https://quran.com/40/60','Quranic mention of calling upon Allah.','pending','2');
